// Research report (Markdown) and experiment table (CSV), built only from the
// recorded experiments and measurements. Nothing here is generated by a model.
import type { Experiment, ResearchView } from "../../shared/research.js";
import { STRATEGY_LABELS } from "../../shared/research.js";
import { AGENT_NAMES } from "../envelope.js";

const fmt = (n: number | null | undefined) => (n == null ? "—" : Number(n.toPrecision(5)).toString());
const one = (s: string | null | undefined, max = 300) => (s ?? "").replace(/\s+/g, " ").trim().slice(0, max);
/** One sentence, ending in exactly one full stop. */
const sentence = (s: string | null | undefined, max = 300) => one(s, max).replace(/[.\s]+$/, "") + ".";

export function markdownReport(v: ResearchView): string {
  const { run, experiments, summary } = v;
  const byId = new Map(experiments.map((e) => [e.id, e]));
  const label = (e: Experiment | undefined) => (e ? `E${e.seq}` : "—");
  const exps = experiments.filter((e) => e.kind === "experiment");
  const decided = exps.filter((e) => e.decision);
  const kept = decided.filter((e) => e.decision === "keep");
  const rejected = decided.filter((e) => e.decision !== "keep");
  const best = run.bestId ? byId.get(run.bestId) : undefined;
  const baseline = run.baselineId ? byId.get(run.baselineId) : undefined;
  const lineage: Experiment[] = [];
  for (let e = best; e; e = e.parentId ? byId.get(e.parentId) : undefined) lineage.unshift(e);
  const open = exps.filter((e) => !e.decision && e.status !== "cancelled");
  const inconclusive = decided.filter((e) => e.decision === "inconclusive");
  const lessons = decided.filter((e) => e.lessons);
  const metric = run.eval.metricName;

  const lines = [
    `# AutoResearch report: ${run.title}`,
    "",
    `*Generated by Team Room from its experiment records on ${new Date().toISOString().slice(0, 16).replace("T", " ")} UTC. Status: ${run.status}.*`,
    "",
    "## Objective",
    run.objective,
    "",
    `- Repository: \`${run.repoPath}\` (${run.projectTitle ?? run.projectId}), baseline \`${run.baseRef}\` = \`${run.baseSha?.slice(0, 12) ?? "—"}\``,
    run.eval.kind === "command"
      ? `- Evaluation: \`${run.eval.command}\`, ${run.eval.repeats} run(s), median of \`${metric}\`, ${run.eval.direction}; a change must beat the best by more than ${Math.round(run.eval.minImprovement * 100)}% and the measured noise. Protected: ${run.eval.protectedPaths.join(", ") || "none"}.`
      : `- Evaluation: assisted. The human lead judged each experiment against: ${run.eval.criteria}`,
    `- Allowed scope: ${run.allowedScope.join(", ") || "anything outside protected paths"}`,
    `- Strategy: ${STRATEGY_LABELS[run.strategy]}. Researcher: ${AGENT_NAMES[run.roles.researcher]}. Implementers: ${run.roles.implementers.map((k) => AGENT_NAMES[k]).join(", ")}. Evaluator: ${run.roles.evaluator === "other" ? "the other agent" : run.roles.evaluator === "off" ? "off" : AGENT_NAMES[run.roles.evaluator]}.`,
    "",
    "## Result",
    best && baseline
      ? best.id === baseline.id
        ? `No experiment beat the baseline (${metric} ${fmt(baseline.metric)}).`
        : `**Best reproducible result: E${best.seq}, ${metric} ${fmt(best.metric)}** vs baseline ${fmt(baseline.metric)}${summary.improvementPct != null ? ` (**${summary.improvementPct}%** better)` : ""}. It is commit \`${best.commitSha?.slice(0, 12)}\` on branch \`${best.branch}\`. To reproduce: check out that branch and run the evaluation command. Team Room did not merge it into your branch.`
      : "The baseline was not measured.",
    "",
    lineage.length > 1 ? `Path to the best result: ${lineage.map((e) => `E${e.seq}${e.kind === "baseline" ? " (baseline)" : ` ${e.title}`}`).join(" → ")}` : "",
    "",
    `## What was attempted (${exps.length} experiments, ${decided.length} decided, ${kept.length} kept)`,
    "",
    "| Exp | Parent | Approach | Agent | Metric | Decision | Reason |",
    "| --- | --- | --- | --- | --- | --- | --- |",
    ...exps.map(
      (e) =>
        `| E${e.seq} | ${label(e.parentId ? byId.get(e.parentId) : undefined)} | ${one(e.approach, 40) || "—"} | ${e.agentKind ? AGENT_NAMES[e.agentKind] : "—"} | ${fmt(e.metric)} | ${e.decision ?? e.status} | ${one(e.decisionReason, 160).replace(/\|/g, "\\|")} |`,
    ),
    "",
    "## What improved",
    kept.length ? kept.map((e) => `- **E${e.seq} ${e.title}** — ${sentence(e.hypothesis)} ${one(e.decisionReason)}`).join("\n") : "- Nothing yet.",
    "",
    "## What failed, and why it was rejected",
    rejected.length ? rejected.map((e) => `- **E${e.seq} ${e.title}** (${e.decision}) — ${one(e.decisionReason, 400)}`).join("\n") : "- Nothing was rejected.",
    "",
    "## Lessons supported by the evidence",
    lessons.length ? lessons.map((e) => `- E${e.seq}: ${one(e.lessons, 500)}`).join("\n") : "- None recorded yet.",
    "",
    "## Remaining uncertainty",
    [
      inconclusive.length ? `- ${inconclusive.length} experiment(s) were within measurement noise: ${inconclusive.map((e) => `E${e.seq}`).join(", ")}.` : "",
      baseline?.metricSpread != null ? `- Baseline measurements varied by ${(baseline.metricSpread * 100).toFixed(1)}% between runs.` : "",
      run.eval.kind === "command" ? "- The evaluation covers only its own inputs; behaviour beyond them was checked by the evaluator agent's review, not by measurement." : "",
      open.length ? `- ${open.length} experiment(s) did not finish: ${open.map((e) => `E${e.seq}`).join(", ")}.` : "",
      "- Usage cost is not reported by T3 0.1.7, so spending is unknown.",
    ]
      .filter(Boolean)
      .join("\n"),
    "",
    "## Recommended next experiments",
    recommendations(v).map((r) => `- ${r}`).join("\n"),
    "",
  ];
  return lines.filter((l, i, a) => !(l === "" && a[i - 1] === "")).join("\n");
}

function recommendations(v: ResearchView): string[] {
  const { experiments, run } = v;
  const out: string[] = [];
  const proposed = experiments.filter((e) => e.status === "proposed" || (e.status === "cancelled" && !e.decision && /limit|stopped/i.test(e.decisionReason ?? "")));
  for (const e of proposed.slice(0, 3)) out.push(`E${e.seq} (queued, not run): ${e.title} — ${one(e.hypothesis, 200)}`);
  const inconclusive = experiments.filter((e) => e.decision === "inconclusive");
  if (inconclusive.length) out.push(`Re-measure ${inconclusive.map((e) => `E${e.seq}`).join(", ")} with more repeats; they may be small real gains.`);
  const best = experiments.find((e) => e.id === run.bestId);
  if (best && best.kind === "experiment") out.push(`Refine E${best.seq} further, or test whether its gain holds on inputs beyond the evaluation's.`);
  if (!out.length) out.push("Run more experiments from the current best, trying an approach family not used yet.");
  return out;
}

const csvCell = (v: unknown) => {
  const s = v == null ? "" : typeof v === "object" ? JSON.stringify(v) : String(v);
  return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};

export function experimentsCsv(v: ResearchView): string {
  const byId = new Map(v.experiments.map((e) => [e.id, e]));
  const header = ["id", "parent", "kind", "source", "title", "approach", "hypothesis", "agent", "model", "branch", "commit", "metric", "spread", "passed", "decision", "reason", "evaluator_verdict", "changed_files", "retries", "pinned", "rejected", "started_at", "finished_at", "lessons", "params", "metrics"];
  const rows = v.experiments.map((e) => [
    `E${e.seq}`,
    e.parentId ? `E${byId.get(e.parentId)?.seq}` : "",
    e.kind,
    e.source,
    e.title,
    e.approach,
    e.hypothesis,
    e.agentKind ?? "",
    e.model ?? "",
    e.branch ?? "",
    e.commitSha ?? "",
    e.metric ?? "",
    e.metricSpread ?? "",
    e.passed ?? "",
    e.decision ?? e.status,
    e.decisionReason ?? "",
    e.reviewVerdict ?? "",
    e.changedFiles.join(" "),
    e.retries,
    e.pinned,
    e.rejected,
    e.startedAt ?? "",
    e.finishedAt ?? "",
    e.lessons ?? "",
    e.params,
    e.metrics,
  ]);
  return [header, ...rows].map((r) => r.map(csvCell).join(",")).join("\n") + "\n";
}
